export const DDDBreakpoints=Object.freeze({sm:600,md:900,lg:1200,xl:1440});export const DDDContentWidths=Object.freeze({sm:640,md:840,lg:960});export const DDDSidebarWidths=Object.freeze({rail:56,sm:240,md:300,lg:360});export const DDDContainerWidths=Object.freeze({md:1200,lg:1440});export const DDDLayout=Object.freeze({breakpoint:DDDBreakpoints,contentWidth:DDDContentWidths,sidebarWidth:DDDSidebarWidths,containerWidth:DDDContainerWidths});export function dddSizeForWidth(t=0){return t>=DDDBreakpoints.xl?"xl":t>=DDDBreakpoints.lg?"lg":t>=DDDBreakpoints.md?"md":t>=DDDBreakpoints.sm?"sm":"xs"}